SELECT 
FROM TBL_FINANCING_COST_ANALYSIS
WHERE 1=1

    AND FINANCING_ID = #{financingId}


    AND FINANCING_TYPE = #{financingType}


    AND CURRENCY_CODE = #{currencyCode}


    AND COMPANY_ID = #{companyId}


    AND PERIOD_TYPE = #{periodType}


    AND PERIOD_VALUE = #{periodValue}


    AND ANALYSIS_DATE >= #{startDate}


    AND ANALYSIS_DATE <= #{endDate}


    AND COST_RATE >= #{minCostRate}


    AND COST_RATE <= #{maxCostRate}

ORDER BY ANALYSIS_DATE DESC

SELECT COUNT(*)
FROM TBL_FINANCING_COST_ANALYSIS
WHERE 1=1

    AND FINANCING_ID = #{financingId}


    AND FINANCING_TYPE = #{financingType}


    AND CURRENCY_CODE = #{currencyCode}


    AND COMPANY_ID = #{companyId}


    AND PERIOD_TYPE = #{periodType}


    AND PERIOD_VALUE = #{periodValue}


    AND ANALYSIS_DATE >= #{startDate}


    AND ANALYSIS_DATE <= #{endDate}


    AND COST_RATE >= #{minCostRate}


    AND COST_RATE <= #{maxCostRate}

SELECT COUNT(*) AS "totalCount", NVL(SUM(PRINCIPAL_AMOUNT), 0) AS "totalPrincipal", NVL(SUM(INTEREST_EXPENSE), 0) AS "totalInterest", NVL(SUM(FEE_COST), 0) AS "totalFee", NVL(SUM(GUARANTEE_COST), 0) AS "totalGuarantee", NVL(SUM(OTHER_COST), 0) AS "totalOther", NVL(SUM(TOTAL_COST), 0) AS "totalCost", NVL(ROUND(AVG(COST_RATE), 2), 0) AS "avgCostRate", NVL(MAX(COST_RATE), 0) AS "maxCostRate", NVL(MIN(COST_RATE), 0) AS "minCostRate" FROM TBL_FINANCING_COST_ANALYSIS WHERE 1=1
AND COMPANY_ID = #{companyId}
AND PERIOD_TYPE = #{periodType}
AND PERIOD_VALUE = #{periodValue}

SELECT FINANCING_TYPE, CURRENCY_CODE, COUNT(*) AS count, SUM(PRINCIPAL_AMOUNT) AS totalPrincipal, SUM(TOTAL_COST) AS totalCost, AVG(COST_RATE) AS avgCostRate FROM TBL_FINANCING_COST_ANALYSIS WHERE 1=1
AND COMPANY_ID = #{companyId}
AND PERIOD_TYPE = #{periodType}
AND PERIOD_VALUE = #{periodValue}
GROUP BY FINANCING_TYPE, CURRENCY_CODE ORDER BY FINANCING_TYPE
